apply.script:
$db = "$Env:LocalAppData\Packages\Microsoft.WindowsStore_8wekyb3d8bbwe\LocalState\store.db"
if (Test-Path $db) {
    icacls $db /deny "*S-1-1-0:F" | Out-Null
    if ($LASTEXITCODE -ne 0) { throw "icacls failed with exit code $LASTEXITCODE" }
}

# Disable Defender Auto Sample Submission
      if (Get-Command Set-MpPreference -ErrorAction SilentlyContinue) {
          Set-MpPreference -SubmitSamplesConsent 2 -ErrorAction SilentlyContinue
      }

      # Disable (Connected User Experiences and Telemetry) Service
      if (Get-Service -Name diagtrack -ErrorAction SilentlyContinue) {
          Set-Service -Name diagtrack -StartupType Disabled -ErrorAction SilentlyContinue
      }

      # Disable (Windows Error Reporting Service)
      if (Get-Service -Name WerSvc -ErrorAction SilentlyContinue) {
          Set-Service -Name WerSvc -StartupType Disabled -ErrorAction SilentlyContinue
      }

      # Disable PowerShell 7 telemetry
      [Environment]::SetEnvironmentVariable('POWERSHELL_TELEMETRY_OPTOUT', '1', 'Machine')

      Remove-ItemProperty -Path "HKCU:\Software\Microsoft\Siuf\Rules" -Name PeriodInNanoSeconds -ErrorAction SilentlyContinue

undo.script:
# Enable Defender Auto Sample Submission
      if (Get-Command Set-MpPreference -ErrorAction SilentlyContinue) {
          Set-MpPreference -SubmitSamplesConsent 1 -ErrorAction SilentlyContinue
      }

      # Enable (Connected User Experiences and Telemetry) Service
      if (Get-Service -Name diagtrack -ErrorAction SilentlyContinue) {
          Set-Service -Name diagtrack -StartupType Automatic -ErrorAction SilentlyContinue
      }

      # Enable (Windows Error Reporting Service)
      if (Get-Service -Name WerSvc -ErrorAction SilentlyContinue) {
          Set-Service -Name WerSvc -StartupType Manual -ErrorAction SilentlyContinue
      }

      # Enable PowerShell 7 telemetry
      [Environment]::SetEnvironmentVariable('POWERSHELL_TELEMETRY_OPTOUT', '', 'Machine')

apply.script:
Start-Process -FilePath "$Env:SystemRoot\System32\cleanmgr.exe" -ArgumentList '/sagerun:1' -Wait
Dism.exe /online /Cleanup-Image /StartComponentCleanup /ResetBase
if ($LASTEXITCODE -ne 0 -and $LASTEXITCODE -ne 3010) { throw "Dism failed with exit code $LASTEXITCODE" }
